solutionCode:
pub fn soma_no_lugar(r: &mut i32, valor: i32) -> i32 {
    *r = *r + valor;
    *r
}

testsCode:
use desafio::soma_no_lugar;

#[test]
fn testa_a_soma_no_placar_de_dez() {
    let mut placar = 10;
    let novo = soma_no_lugar(&mut placar, 5);
    assert_eq!(novo, 15);
    assert_eq!(placar, 15);
}

#[test]
fn testa_a_soma_no_placar_de_dois() {
    let mut placar = 2;
    let novo = soma_no_lugar(&mut placar, 3);
    assert_eq!(novo, 5);
    assert_eq!(placar, 5);
}
